54	/// What the MHPCO settles on a claim: the payout and the cap left on the
55	/// policy afterwards.
56	#[derive(Debug)]
57	pub struct ClaimResult {
58	    pub payout: u64,
59	    pub remaining_cap: u64,
60	}
61	
62	/// The single customer a scenario is quoted for.
63	pub struct Customer {
64	    pub years_with_mhpco: u32,
65	}
66	
67	pub struct Item {
68	    pub item_type: String,
69	    pub material: String,
70	    pub enchantment: u32,
71	    pub cursed: bool,
72	}
73	
74	const PROCESSING_FEE: u64 = 5;
75	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
76	const CAP_MULTIPLE_OF_INSURANCE_SUM: u64 = 2;
77	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL: u32 = 8;
78	const HALF_REIMBURSEMENT_PERCENT: u64 = 50;
79	
80	const SWORD_INSURANCE_VALUE: u64 = 1000;
81	const AMULET_INSURANCE_VALUE: u64 = 600;
82	const STAFF_INSURANCE_VALUE: u64 = 800;
83	const POTION_INSURANCE_VALUE: u64 = 400;
84	const COMPONENT_INSURANCE_VALUE: u64 = 250;
85	const SWORD_BASE_PREMIUM: u64 = 100;
86	const AMULET_BASE_PREMIUM: u64 = 60;
87	const STAFF_BASE_PREMIUM: u64 = 80;
88	const POTION_BASE_PREMIUM: u64 = 40;
89	const COMPONENT_BASE_PREMIUM: u64 = 25;
90	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
91	const COMPONENT_BLOCK_SIZE: usize = 3;
92	const CURSE_SURCHARGE_PERCENT: u64 = 50;
93	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
94	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
95	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
96	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
97	const LOYALTY_YEARS: u32 = 2;
98	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
99	
100	/// Components, such as runes and moonstones, are the parts the MHPCO insures
101	/// alongside main items and the only items the building-block offer covers.
102	fn is_component(item: &Item) -> bool {
103	    matches!(item.item_type.as_str(), "rune" | "moonstone")
104	}
105	
106	/// The base premium the MHPCO price list names for one main item, or nothing
107	/// at all when the catalogue does not list that type. This is the one place the
108	/// roster of insurable main items is written down: being listed here is what it
109	/// means for the office to insure a type.
110	fn listed_base_premium(item_type: &str) -> Option<u64> {
111	    match item_type {
112	        "sword" => Some(SWORD_BASE_PREMIUM),
113	        "amulet" => Some(AMULET_BASE_PREMIUM),
114	        "staff" => Some(STAFF_BASE_PREMIUM),
115	        "potion" => Some(POTION_BASE_PREMIUM),
116	        _ => None,
117	    }
118	}
119	
120	/// The MHPCO insures the components it recognises and the main items its price
121	/// list names; it insures nothing else.
122	fn is_in_catalogue(item: &Item) -> bool {
123	    is_component(item) || listed_base_premium(&item.item_type).is_some()
124	}
125	
126	/// The MHPCO can only price the items its catalogue lists.
127	fn check_every_item_is_in_the_catalogue(items: &[Item]) -> Result<(), QuoteError> {
128	    match items.iter().find(|item| !is_in_catalogue(item)) {
129	        Some(unknown) => Err(QuoteError::UnknownItemType {
130	            item_type: unknown.item_type.clone(),
131	        }),
132	        None => Ok(()),
133	    }
134	}
135	
136	/// The base premium one insured item earns. Every component is priced alike;
137	/// a main item is priced by the price list. The catalogue guard has already
138	/// refused anything the list does not name, so a priced item is always listed.
139	fn base_premium(item: &Item) -> u64 {
140	    if is_component(item) {
141	        return COMPONENT_BASE_PREMIUM;
142	    }
143	    listed_base_premium(&item.item_type).expect("the catalogue lists this item type")
144	}
145	
146	/// The building-block offer is reserved for a group of exactly 3 alike
147	/// components; a larger group does not qualify, it is priced per component.
148	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
149	    alike_component_count == COMPONENT_BLOCK_SIZE
150	}
151	
152	/// The price the MHPCO charges for one group of alike components: the
153	/// building-block offer when the group qualifies, otherwise per component.
154	fn component_group_base_premium(count: usize) -> u64 {
155	    if qualifies_as_building_block(count) {
156	        COMPONENT_BLOCK_BASE_PREMIUM
157	    } else {
158	        count as u64 * COMPONENT_BASE_PREMIUM
159	    }
160	}
161	
162	/// How many entries fall under each key a list of items is grouped by. The
163	/// MHPCO tallies items this way wherever a rule counts like with like: the
164	/// claim side groups by catalogue type to match damages against cover, the
165	/// premium side by alike-group key to recognise a building block.
166	fn count_by_item_type<'a>(
167	    item_types: impl Iterator<Item = &'a str>,
168	) -> BTreeMap<&'a str, usize> {
169	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
170	    for item_type in item_types {
171	        *counts.entry(item_type).or_insert(0) += 1;
172	    }
173	    counts
174	}
175	
176	/// Two components are "alike" when they share this key. For the MHPCO,
177	/// alike means the very same catalogue type: a rune and a moonstone are
178	/// never alike, so mixed component types form no building block.
179	fn alike_group_key(item: &Item) -> &str {
180	    &item.item_type
181	}
182	
183	/// The policy base premium: the sum of all insured items' base premiums,
184	/// with alike components priced per group so a block can be recognised.
185	fn policy_base_premium(items: &[Item]) -> u64 {
186	    let main_items_total: u64 = items
187	        .iter()
188	        .filter(|item| !is_component(item))
189	        .map(base_premium)
190	        .sum();
191	
192	    let alike_component_groups = count_by_item_type(
193	        items
194	            .iter()
195	            .filter(|item| is_component(item))
196	            .map(alike_group_key),
197	    );
198	
199	    main_items_total
200	        + alike_component_groups
201	            .values()
202	            .map(|count| component_group_base_premium(*count))
203	            .sum::<u64>()
204	}
205	
206	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
207	#[derive(Clone, Copy)]
208	enum Debtor {
209	    Customer,
210	    Mhpco,
211	}
212	
213	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
214	/// settles the direction by itself once it is known who owes whom: an amount
215	/// the customer owes is rounded up, an amount the office owes is rounded down.
216	/// Intermediate amounts stay fractional; only the final amount is rounded.
217	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
218	    match owed_by {
219	        Debtor::Customer => amount.ceil() as u64,
220	        Debtor::Mhpco => amount.floor() as u64,
221	    }
222	}
223	
224	/// A policy-wide modifier is measured against the policy base premium, the
225	/// sum of all item base premiums, never against a single item.
226	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
227	    policy_base_premium * percent as f64 / 100.0
228	}
229	
230	/// Every item in a quote is treated as a first insurance, so the initial
231	/// assessment surcharge is charged on the whole policy base premium.
232	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
233	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
234	}
235	
236	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
237	/// highly enchanted. This is the premium-side threshold; the claim-side
238	/// reimbursement clause judges enchantment by its own, stricter threshold.
239	fn is_highly_enchanted(item: &Item) -> bool {
240	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
241	}
242	
243	/// An item-specific risk surcharge is charged on the base premium of the
244	/// affected item, never on the policy total.
245	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
246	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
247	}
248	
249	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
250	/// item that brings two of them is surcharged for each.
251	fn item_risk_surcharge(item: &Item) -> f64 {
252	    let mut surcharge = 0.0;
253	    if item.cursed {
254	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
255	    }
256	    if is_highly_enchanted(item) {
257	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
258	    }
259	    surcharge
260	}
261	
262	/// Item-specific modifiers apply to the base premium of the affected item,
263	/// never to the policy total, so the policy owes the sum of the items' own
264	/// risk surcharges.
265	fn item_risk_surcharges(items: &[Item]) -> f64 {
266	    items.iter().map(item_risk_surcharge).sum()
267	}
268	
269	/// A long-standing customer, with at least two years of business with the
270	/// MHPCO, has earned the loyalty discount.
271	fn is_long_standing(customer: &Customer) -> bool {
272	    customer.years_with_mhpco >= LOYALTY_YEARS
273	}
274	
275	/// The loyalty discount is a policy-wide modifier, so it is measured against
276	/// the policy base premium.
277	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
278	    if is_long_standing(customer) {
279	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
280	    } else {
281	        0.0
282	    }
283	}
284	
285	/// A contract is a follow-up when the customer already holds at least one
286	/// other contract with the MHPCO; the customer's very first is not.
287	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
288	    contracts_already_held > 0
289	}
290	
291	/// Every contract after the customer's first earns the follow-up discount. It
292	/// is a policy-wide modifier, so it is measured against the policy base premium.
293	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
294	    if is_follow_up_contract(contracts_already_held) {
295	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
296	    } else {
297	        0.0
298	    }
299	}
300	
301	/// What the customer's standing with the MHPCO adds to or takes off the policy
302	/// base premium: the net of every policy-wide surcharge and discount. Positive
303	/// amounts raise the premium, negative amounts lower it.
304	fn policy_wide_modifiers(
305	    customer: &Customer,
306	    contracts_already_held: u32,
307	    policy_base_premium: f64,
308	) -> f64 {
309	    first_insurance_surcharge(policy_base_premium)
310	        - loyalty_discount(customer, policy_base_premium)
311	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
312	}
313	
314	/// The premium the policy earns before the processing fee: the policy base
315	/// premium, plus what the items' own risks cost, plus what the customer's
316	/// standing adjusts.
317	fn modified_policy_premium(
318	    customer: &Customer,
319	    contracts_already_held: u32,
320	    items: &[Item],
321	) -> f64 {
322	    let policy_base_premium = policy_base_premium(items) as f64;
323	    policy_base_premium
324	        + item_risk_surcharges(items)
325	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
326	}
327	
328	/// The MHPCO adds its processing fee to every premium at the very end, after
329	/// every surcharge and discount has been settled.
330	pub fn quote_premium(
331	    customer: &Customer,
332	    contracts_already_held: u32,
333	    items: &[Item],
334	) -> Result<u64, QuoteError> {
335	    check_every_item_is_in_the_catalogue(items)?;
336	    Ok(rounded_in_mhpco_favor(
337	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
338	        Debtor::Customer,
339	    ))
340	}
341	
342	/// Damage to a very highly enchanted item is reimbursed at only half the
343	/// damage amount. This claim-side threshold is deliberately stricter than, and
344	/// separate from, the premium-side high-enchantment risk surcharge: an item can
345	/// be enchanted enough to cost more to insure yet not enough to be halved.
346	fn is_reimbursed_by_half(item: &Item) -> bool {
347	    item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
348	}
349	
350	/// How much of a reported damage the MHPCO's reimbursement clauses cover,
351	/// before the deductible is taken off. Full reimbursement is the MHPCO's
352	/// standing position: it is both what an item with no clause receives and what
353	/// the dragon-material clause prescribes, so that clause asks for no share of
354	/// its own. Only the halving clause departs from full reimbursement, and it
355	/// wins wherever it applies.
356	fn covered_damage(damaged_item: &Item, damage: &Damage) -> f64 {
357	    if is_reimbursed_by_half(damaged_item) {
358	        damage.amount as f64 * HALF_REIMBURSEMENT_PERCENT as f64 / 100.0
359	    } else {
360	        damage.amount as f64
361	    }
362	}
363	
364	/// The deductible applies per damage event, after the reimbursement clauses.
365	fn reimbursement_for(damaged_item: &Item, damage: &Damage) -> f64 {
366	    (covered_damage(damaged_item, damage) - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
367	}
368	
369	/// Which insured item a reported damage refers to. A damage names only a
370	/// catalogue type, so the policy is searched for an item of that type; the
371	/// reimbursement clauses are judged against the item found here, not the report.
372	fn insured_item_for<'a>(items: &'a [Item], damage: &Damage) -> &'a Item {
373	    items
374	        .iter()
375	        .find(|item| item.item_type == damage.item_type)
376	        .expect("the damaged item is insured by this policy")
377	}
378	
379	/// What the MHPCO owes for an incident filed against a policy: the sum of the
380	/// reimbursements its damages earn, rounded in the office's favor at the end.
381	pub fn claim_payout(items: &[Item], incident: &Incident) -> u64 {
382	    let total: f64 = incident
383	        .damages
384	        .iter()
385	        .map(|damage| reimbursement_for(insured_item_for(items, damage), damage))
386	        .sum();
387	    rounded_in_mhpco_favor(total, Debtor::Mhpco)
388	}
389	
390	/// The MHPCO price list also lists what each item is insured for. The office
391	/// has so far only had to pay out on the entries named here; a staff or a
392	/// potion is admitted to the catalogue and priced a premium, but no claim has
393	/// yet asked what it is insured for, so no figure is written down for it.
394	fn insurance_value(item: &Item) -> u64 {
395	    if is_component(item) {
396	        return COMPONENT_INSURANCE_VALUE;
397	    }
398	    match item.item_type.as_str() {
399	        "amulet" => AMULET_INSURANCE_VALUE,
400	        "staff" => STAFF_INSURANCE_VALUE,
401	        "potion" => POTION_INSURANCE_VALUE,
402	        _ => SWORD_INSURANCE_VALUE,
403	    }
404	}
405	
406	/// The insurance sum of a policy is the sum of its items' insurance values.
407	fn insurance_sum(items: &[Item]) -> u64 {
408	    items.iter().map(insurance_value).sum()
409	}
410	
411	/// The total payout per policy is capped at twice the insurance sum.
412	fn policy_cap(items: &[Item]) -> u64 {
413	    CAP_MULTIPLE_OF_INSURANCE_SUM * insurance_sum(items)
414	}
415	
416	/// How the cap limits one settlement: the MHPCO pays what the incident earned,
417	/// but never more than the cap the policy has left, and reports the cap that
418	/// survives the payout.
419	fn settled_within_cap(earned: u64, available_cap: u64) -> ClaimResult {
420	    let payout = earned.min(available_cap);
421	    ClaimResult {
422	        payout,
423	        remaining_cap: available_cap - payout,
424	    }
425	}
426	
427	/// How much of its cap a policy still has to pay out with, once earlier claims
428	/// have drawn on it. A cap can be drawn down until it is exhausted, and an
429	/// exhausted cap is simply nothing left, never a debt the policy owes back.
430	fn cap_remaining_on(items: &[Item], cap_already_consumed: u64) -> u64 {
431	    policy_cap(items).saturating_sub(cap_already_consumed)
432	}
433	
434	/// How many items of a catalogue type a policy insures. A type the policy never
435	/// mentions is insured none of: the MHPCO holds no cover for what it did not
436	/// write down.
437	fn insured_count_of(insured_counts: &BTreeMap<&str, usize>, item_type: &str) -> usize {
438	    insured_counts.get(item_type).copied().unwrap_or(0)
439	}
440	
441	/// Every reported damage must be covered by an insured item of its own. The
442	/// office compares the damages it was sent against the policy type by type, so a
443	/// type damaged twice needs two insured items of that type to stand. One
444	/// comparison decides admissibility; how far it falls short decides which
445	/// refusal the claim earns -- a type the policy does not cover at all is refused
446	/// as uninsured, a type covered by too few items as an over-count.
447	fn check_policy_covers_every_damage(
448	    items: &[Item],
449	    incident: &Incident,
450	) -> Result<(), ClaimError> {
451	    let insured = count_by_item_type(items.iter().map(|item| item.item_type.as_str()));
452	    for (item_type, reported) in
453	        count_by_item_type(incident.damages.iter().map(|damage| damage.item_type.as_str()))
454	    {
455	        let insured_of_that_type = insured_count_of(&insured, item_type);
456	        if insured_of_that_type == 0 {
457	            return Err(ClaimError::ItemNotInsured {
458	                item_type: item_type.to_string(),
459	            });
460	        }
461	        if reported > insured_of_that_type {
462	            return Err(ClaimError::MoreDamagesThanInsuredItems {
463	                item_type: item_type.to_string(),
464	            });
465	        }
466	    }
467	    Ok(())
468	}
469	
470	/// What the MHPCO settles on an incident filed against a policy: what the
471	/// incident earns, limited by the cap the policy has left. The office first
472	/// satisfies itself that the claim is admissible at all; an inadmissible claim
473	/// is refused whole, and nothing is paid out on it.
474	pub fn claim(
475	    items: &[Item],
476	    incident: &Incident,
477	    cap_already_consumed: u64,
478	) -> Result<ClaimResult, ClaimError> {
479	    check_policy_covers_every_damage(items, incident)?;
480	    Ok(settled_within_cap(
481	        claim_payout(items, incident),
482	        cap_remaining_on(items, cap_already_consumed),
483	    ))
484	}
