486	#[cfg(test)]
487	mod tests {
488	    use super::*;
489	
490	    /// A customer with the given number of years of business with the MHPCO,
491	    /// the standing the loyalty discount is judged against.
492	    fn customer_of(years_with_mhpco: u32) -> Customer {
493	        Customer { years_with_mhpco }
494	    }
495	
496	    /// A customer in their first year of business with the MHPCO.
497	    fn newcomer() -> Customer {
498	        customer_of(0)
499	    }
500	
501	    /// A plain, unenchanted, uncursed item of the given catalogue type.
502	    fn plain(item_type: &str) -> Item {
503	        Item {
504	            item_type: item_type.to_string(),
505	            material: "steel".to_string(),
506	            enchantment: 0,
507	            cursed: false,
508	        }
509	    }
510	
511	    /// How many contracts the customer already holds when a quote is made: the
512	    /// standing the follow-up contract discount is judged against. The very
513	    /// first contract earns no discount; every later one does.
514	    const FIRST_CONTRACT: u32 = 0;
515	    const SECOND_CONTRACT: u32 = 1;
516	    const THIRD_CONTRACT: u32 = 2;
517	
518	    /// The premium the MHPCO quotes for a policy it can price. Every premium
519	    /// example below names a catalogued item, so the quote is always priced;
520	    /// the refusal channel is the subject of its own tests, not of these.
521	    fn premium_of(customer: &Customer, contracts_already_held: u32, items: &[Item]) -> u64 {
522	        quote_premium(customer, contracts_already_held, items).expect("the quote is priced")
523	    }
524	
525	    /// A group of `count` alike components, the shape the building-block
526	    /// offer is judged against.
527	    fn alike(count: usize, item_type: &str) -> Vec<Item> {
528	        (0..count).map(|_| plain(item_type)).collect()
529	    }
530	
531	    /// An incident reporting one damage per `(item type, amount)` pair, the
532	    /// shape a claim is filed as: the deductible is judged per damage entry,
533	    /// so each pair stands for one damage event.
534	    fn incident_of(damages: &[(&str, i64)]) -> Incident {
535	        Incident {
536	            damages: damages
537	                .iter()
538	                .map(|(item_type, amount)| Damage {
539	                    item_type: item_type.to_string(),
540	                    amount: *amount,
541	                })
542	                .collect(),
543	        }
544	    }
545	
546	    /// What the MHPCO pays when a policy covering just `item` is hit by a
547	    /// single damage of `amount` to that item: the shape every reimbursement
548	    /// clause example is stated in, so each test shows only the item trait the
549	    /// clause turns on and the payout it earns.
550	    fn payout_for_single_damage(item: Item, amount: i64) -> u64 {
551	        let item_type = item.item_type.clone();
552	        claim_payout(&[item], &incident_of(&[(&item_type, amount)]))
553	    }
